public class DateTimeZone_forOffsetHoursMinutes_TriageGen2Test {

    @Test
    public void testForOffsetHoursMinutes_UTC() {
        DateTimeZone zone = DateTimeZone.forOffsetHoursMinutes(0, 0);
        assertEquals(DateTimeZone.UTC, zone);
    }

    @Test
    public void testForOffsetHoursMinutes_PositiveOffset() {
        // Test +5:30
        DateTimeZone zone = DateTimeZone.forOffsetHoursMinutes(5, 30);
        int expectedMillis = (5 * 60 + 30) * DateTimeConstants.MILLIS_PER_MINUTE;
        assertEquals(expectedMillis, zone.getOffset(0));
    }

    @Test
    public void testForOffsetHoursMinutes_NegativeOffset() {
        // Test -5:30
        // Logic: hoursInMinutes = -300. minutesOffset = -300 - abs(30) = -330.
        DateTimeZone zone = DateTimeZone.forOffsetHoursMinutes(-5, 30);
        int expectedMillis = (-5 * 60 - 30) * DateTimeConstants.MILLIS_PER_MINUTE;
        assertEquals(expectedMillis, zone.getOffset(0));
    }

    @Test
    public void testForOffsetHoursMinutes_BoundaryPositive() {
        // Max valid: +23:59
        DateTimeZone zone = DateTimeZone.forOffsetHoursMinutes(23, 59);
        int expectedMillis = (23 * 60 + 59) * DateTimeConstants.MILLIS_PER_MINUTE;
        assertEquals(expectedMillis, zone.getOffset(0));
    }

    @Test
    public void testForOffsetHoursMinutes_BoundaryNegative() {
        // Min valid: -23:59
        DateTimeZone zone = DateTimeZone.forOffsetHoursMinutes(-23, 59);
        int expectedMillis = (-23 * 60 - 59) * DateTimeConstants.MILLIS_PER_MINUTE;
        assertEquals(expectedMillis, zone.getOffset(0));
    }

    @Test(expected = IllegalArgumentException.class)
    public void testForOffsetHoursMinutes_HoursTooHigh() {
        DateTimeZone.forOffsetHoursMinutes(24, 0);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testForOffsetHoursMinutes_HoursTooLow() {
        DateTimeZone.forOffsetHoursMinutes(-24, 0);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testForOffsetHoursMinutes_MinutesTooHigh() {
        DateTimeZone.forOffsetHoursMinutes(5, 60);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testForOffsetHoursMinutes_MinutesNegative() {
        // Note: The code checks minutesOffset < 0. 
        // Even if hours are negative, the parameter minutesOffset must be 0-59 per the check.
        DateTimeZone.forOffsetHoursMinutes(-5, -30);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testForOffsetHoursMinutes_PositiveHoursNegativeMinutes() {
        // Explicit check: if (hoursOffset > 0 && minutesOffset < 0)
        // While the minutes < 0 check happens first, this ensures coverage of the specific logic branch.
        // However, because minutes < 0 is checked first, we trigger that exception.
        DateTimeZone.forOffsetHoursMinutes(5, -1);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testForOffsetHoursMinutes_ArithmeticException() {
